@pytest.mark.anyio
async def test_tool_call_category(server, spans: SpanCapture):
    server.add_request_handler("tools/call", CallToolRequestParams, _ok_tool)
    async with server.run_in_process() as (client, _):
        spans.clear()
        await client.send_raw_request("tools/call", {"name": "mytool", "arguments": {}})
    [span] = [s for s in spans.finished() if s.name.startswith("tools/call")]
    assert span.attributes["mcp.method.category"] == "tool"

